# Frozen Duck Core engine v4_0: generated by tools/freeze_engine.py from 79cc25d:src/duckmind/expression_sweep/looks.py; do not edit.
"""The looks the camera-first design needs (spec §4.2), as head clips for the sweep only.

Duck Core does not know these clips: they live here so the A100 sweep validates the poses
before any behaviour uses them. Content's own ``peek_down``, ``look_up`` and ``glance`` are
expressions with other angles and ~4 s holds, not these looks.

Frames use Duck Core's clip semantics (fractions of ``content.SEATED_ENVELOPE``, offsets
from HOME; ``np`` + leans the head forward and down, ``hp`` + looks up, ``hy`` + turns toward
the habitual side) and go through robotd's head path like every other clip. Head angles
come from the spec's camera table (§4.1, kinematics on the official MJCF,
``survey_calibration.md`` §2.2):

* half down (np +0.5, hp −0.5): camera 0.228 m, axis −17°, floor visible from 0.20 m;
* up (hp +1): camera 0.261 m, axis +20°;
* the seated HOME head: camera 0.198 m, axis 0°, floor visible from 0.32 m — the sitstand
  network holds the head at HOME plus the command while seated (the SIT keyframe's head,
  63° down, is only a spawn pose).

Each look holds its pose long enough for robotd's slew, the network and the spec's 150 ms
stillness rule, then takes a frame; ``CAPTURES_MS`` are those instants (tempo 1.0) at which
the sweep reads where the camera actually points and whether the head was still.
"""

from __future__ import annotations

import math

HALF_DOWN = {"np": 0.5, "hp": -0.5}
UP = {"hp": 1.0}
# Head yaw fraction for an aimed look: 0.54 rad toward the side, the ±0.55 rad head turn
# the spec allows for aiming a look (a planned route's 0.3 m point, a nest bearing).
AIM = 0.9

_P = dict[str, float]

CLIPS: dict[str, list[tuple[int, _P]]] = {
    # Before walking (spec §4.2 glance_down): head down 0.3 s, settle 0.15 s, frame; then
    # the same look aimed along a new heading; head back 0.3 s (the tail settles at HOME).
    "look.glance_down": [
        (0, {}),
        (300, dict(HALF_DOWN)),
        (500, dict(HALF_DOWN)),
        (800, dict(HALF_DOWN, hy=AIM)),
        (1000, dict(HALF_DOWN, hy=AIM)),
        (1300, {}),
    ],
    # Hearing a sound or the name (spec §4.2 look_up): up +20°, one or two frames, ~1 s.
    "look.up": [
        (0, {}),
        (300, dict(UP)),
        (800, dict(UP)),
        (1100, {}),
    ],
    # Seated (spec §4.2 rule 6): the seated HOME head, a frame, then an idle glance aside.
    "look.seated": [
        (0, {}),
        (300, {}),
        (700, {"hy": AIM}),
        (1000, {"hy": AIM}),
        (1400, {}),
    ],
    # Control, not a look: HOME held as long as the longest look. How far a duck drifts and
    # tips with no head motion at all, so "negligible drift" is measured against it.
    "look.hold": [(0, {}), (1400, {})],
}
CONTROL = "look.hold"
LOOKS = tuple(name for name in CLIPS if name != CONTROL)
CAPTURES_MS: dict[str, tuple[int, ...]] = {
    "look.glance_down": (500, 1000),
    "look.up": (800,),
    "look.seated": (300, 1000),
    "look.hold": (300, 1000),
}
MAX_CAPTURES = max(len(times) for times in CAPTURES_MS.values())
# Spec §4.2 rule 2: no frame until head joints < 0.2 rad/s and the gyro < 0.3 rad/s for 150 ms.
STILL_HEAD_RAD_S = 0.2
STILL_GYRO_RAD_S = 0.3
STILL_S = 0.15
# The camera table the looks are built from (spec §4.1): pose → (height m, axis pitch °).
DESIGN_CAMERA = {
    "home_standing": (0.245, 0.0),
    "half_down": (0.228, -17.0),
    "up": (0.261, 20.0),
    "home_seated": (0.198, 0.0),
}
# Pre-registered gate (spec §17 期1: "0 falls, negligible drift"): at the design amplitude,
# no fall by either rule and drift p95 no more than this above the HOME-hold control.
DRIFT_MARGIN_M = 0.01


def still_ticks(hz: int) -> int:
    """Consecutive control ticks that cover the 150 ms stillness rule."""
    return math.ceil(STILL_S * hz - 1e-9)


def is_look(clip: str) -> bool:
    return clip in CLIPS
